from __future__ import annotations

import inspect
import math
from copy import deepcopy

from bench.dm import _shadow_stage6 as target


def _get_real_calibrator_instance():
    """Find and instantiate the real class that owns the target methods."""
    for _, obj in inspect.getmembers(target, inspect.isclass):
        if (
            obj.__module__ == target.__name__
            and hasattr(obj, "_estimate_source_coverage")
            and hasattr(obj, "_estimate_retrieval_sparsity")
        ):
            try:
                return obj()
            except Exception:
                # The target methods are pure helpers in the current design; if
                # __init__ requires arguments, bypass it so we still exercise the
                # real method bodies.
                return object.__new__(obj)
    raise RuntimeError("Could not locate class with target helper methods")


def _source_name(source_obj):
    if hasattr(source_obj, "source_name"):
        return source_obj.source_name
    if isinstance(source_obj, dict):
        return source_obj.get("source_name") or source_obj.get("source")
    return None


def _status(source_obj):
    if hasattr(source_obj, "status"):
        return source_obj.status
    if isinstance(source_obj, dict):
        return source_obj.get("status")
    return None


def _results_count(source_obj):
    if hasattr(source_obj, "results_count"):
        return source_obj.results_count
    if isinstance(source_obj, dict):
        return source_obj.get("results_count")
    return None


def _call_sparsity(obj, finding, metadata):
    """Call the real sparsity helper while tolerating signature variation."""
    method = obj._estimate_retrieval_sparsity
    sig = inspect.signature(method)
    params = list(sig.parameters)

