            "source_name": "pubmed",
            "tool": "pubmed",
            "database": "pubmed",
            "status": "error",
            "results_count": 0,
            "query": "same query",
        },
        {
            "source": "pubmed",
            "source_name": "pubmed",
            "tool": "pubmed",
            "database": "pubmed",
            "status": "live",
