    ignored_success_retry = (
        _status(pubmed) == retry_snapshot[0]["status"]
        and _results_count(pubmed) == retry_snapshot[0]["results_count"]
        and retry_snapshot[1]["status"] == "live"
        and retry_snapshot[1]["results_count"] > 0
    )

    finding = {
        "finding_id": "falsifier-finding",
        "description": "synthetic finding used only to exercise sparsity helper",
    }

    single_metadata = [
